/** Frame 4631 -- generated by the template lab from Figma node 538:39407
 *  (Frame 4631). Everything is drawn from the board itself
 *  (FigmaLayers); the slots below are what a designer edits, each in its
 *  board place and stacking order:
 *    copy tied to the brief -- offer, lead;
 *    board copy, editable -- memorial-day, sale, past-season-styles, new-brands;
 *    photos -- photo; brand slots -- brand/0, brand/1, brand/2, brand/3.
 *  Text contracts come from each board layer (boardFit). NUDGE (./nudges.ts)
 *  holds the fix loop's per-layer corrections to Figma's render. */
import type { SheetAsset } from '../../../../../sheet/types';
import { Ground } from '../../../../../edit/Editable';
import { Picture } from '../../../../../edit/Picture';
import { ZONE_LIST, photoFor } from '../../../../../model/compose';
import { BrandMark } from '../../../../../render/templates/BrandMark';
import { FigmaLayers, FigmaText, FigmaMark, type Slot } from '../../../../../render/figma/FigmaLayers';
import { cropOf, type FigmaLayout } from '../../../../../render/figma/layout';
import board from './layout.json';
import { NUDGE } from './nudges';

/** Which board layer each editable layer is, by the part of its id after the asset's. */
export const FRAME_4631_538_39407_FIGMA = {
  "offer": "538:39411", // offer: 60% OFF
  "lead": "538:39412", // lead: UP\u2028TO
  "memorial-day": "538:39415", // text: MEMORIAL DAY
  "sale": "538:39418", // text: SALE
  "past-season-styles": "I538:39426;21584:46496", // text: *Past season styles.
  "new-brands": "538:39428", // text: NEW BRANDS!
  "art/ellipse-1": "538:39408", // graphic: Ellipse 1
  "art/vector-741": "538:39409", // graphic: Vector 741
  "brand-logo-frame/brand-logo": "538:39421", // graphic: Brand Logo
  "rab/rab-white": "I538:39425;876:3882", // graphic: Rab / White
  "patagonia/patagonia-white": "I538:39426;21584:46497;876:3734", // graphic: Patagonia / White
  "art/vector-742": "538:39427", // graphic: Vector 742
  "brand/0": "538:39423", // brand: Brand Logo
  "brand/1": "538:39424", // brand: Osprey *NEW
  "brand/2": "538:39425", // brand: Rab
  "brand/3": "538:39426", // brand: Patagonia
} as const;

export function Frame4631_538_39407({ asset }: { asset: SheetAsset }) {
  const layout = board as unknown as FigmaLayout, id = asset.id;
  const zone = ZONE_LIST.find(z => z.id === asset.media.photo) ?? photoFor('hike', 0);
  const slots: Record<string, Slot> = {
    [FRAME_4631_538_39407_FIGMA["offer"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/offer`} contract="lab.offer" layout={layout}
      text={asset.copy.offer || l.text!.chars} />,
    [FRAME_4631_538_39407_FIGMA["lead"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/lead`} contract="lab.lead" layout={layout}
      text={asset.copy.lead ? (l.text!.chars.includes('\u2028') ? asset.copy.lead.replace(/\s+/, '\n') : asset.copy.lead) : l.text!.chars} />,
    [FRAME_4631_538_39407_FIGMA["memorial-day"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/memorial-day`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [FRAME_4631_538_39407_FIGMA["sale"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/sale`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [FRAME_4631_538_39407_FIGMA["past-season-styles"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/past-season-styles`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [FRAME_4631_538_39407_FIGMA["new-brands"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/new-brands`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [FRAME_4631_538_39407_FIGMA["art/ellipse-1"]]: (l, box) => <FigmaMark l={l} box={box} id={`${id}/art/ellipse-1/mark`} src="/graphics/named-sale-ellipse-1-1lnrgsd.svg"
      fill="#303226" layout={layout} />,
    [FRAME_4631_538_39407_FIGMA["art/vector-741"]]: (l, box) => <FigmaMark l={l} box={box} id={`${id}/art/vector-741/mark`} src="/graphics/named-sale-vector-741-1xczcef.svg"
      fill="#F14221" layout={layout} />,
    [FRAME_4631_538_39407_FIGMA["brand-logo-frame/brand-logo"]]: (l, box) => <FigmaMark l={l} box={box} id={`${id}/brand-logo-frame/brand-logo/mark`} src="/graphics/named-sale-brand-logo-13a5vgk.svg"
      fill="#FFFFFF" layout={layout} />,
    [FRAME_4631_538_39407_FIGMA["rab/rab-white"]]: (l, box) => <FigmaMark l={l} box={box} id={`${id}/rab/rab-white/mark`} src="/graphics/named-sale-rab-white-16g3shr.svg"
      fill="#FFFFFF" layout={layout} />,
    [FRAME_4631_538_39407_FIGMA["patagonia/patagonia-white"]]: (l, box) => <FigmaMark l={l} box={box} id={`${id}/patagonia/patagonia-white/mark`} src="/graphics/named-sale-patagonia-white-pksmxb.svg"
      fill="#FFFFFF" layout={layout} />,
    [FRAME_4631_538_39407_FIGMA["art/vector-742"]]: (l, box) => <FigmaMark l={l} box={box} id={`${id}/art/vector-742/mark`} src="/graphics/named-sale-vector-742-o4us53.svg"
      fill="#F14222" layout={layout} />,
    // The board's logo until the brief names a brand.
    [FRAME_4631_538_39407_FIGMA["brand/0"]]: (l, box, _n, board) => asset.media.brands?.[0]
      ? <BrandMark id={`${id}/brand/0`} name={asset.media.brands[0]} fallback="/logos/brand-patagonia.svg"
          style={{ ...box, objectFit: 'contain' }} />
      : board(),
    // The board's logo until the brief names a brand.
    [FRAME_4631_538_39407_FIGMA["brand/1"]]: (l, box, _n, board) => asset.media.brands?.[1]
      ? <BrandMark id={`${id}/brand/1`} name={asset.media.brands[1]} fallback="/logos/brand-osprey.svg"
          style={{ ...box, objectFit: 'contain' }} />
      : board(),
    // The board's logo until the brief names a brand.
    [FRAME_4631_538_39407_FIGMA["brand/2"]]: (l, box, _n, board) => asset.media.brands?.[2]
      ? <BrandMark id={`${id}/brand/2`} name={asset.media.brands[2]} fallback="/logos/brand-rab.svg"
          style={{ ...box, objectFit: 'contain' }} />
      : board(),
    // The board's logo until the brief names a brand.
    [FRAME_4631_538_39407_FIGMA["brand/3"]]: (l, box, _n, board) => asset.media.brands?.[3]
      ? <BrandMark id={`${id}/brand/3`} name={asset.media.brands[3]} fallback="/logos/brand-patagonia.svg"
          style={{ ...box, objectFit: 'contain' }} />
      : board(),
  };
  const [w, h] = layout.size;
  // The frame's own photo, swappable, under every layer (and not drawn again by FigmaLayers).
  const photo = layout.frame.images?.[0] && layout.assets?.[layout.frame.images[0].ref];
  const crop = photo && layout.frame.crop ? cropOf(layout.frame.crop, [w, h], [photo.w, photo.h]) : undefined;
  const drawn = { ...layout, frame: { ...layout.frame, paints: layout.frame.paints?.filter(p => p.type !== 'IMAGE') } };
  // data-figma-compiled: the studio's Figma export reads a compiled board's way (toLayers).
  return <Ground id={`${id}/fill`} className="sheet" data-figma-compiled="" style={{ width: w, height: h, position: 'relative', overflow: 'hidden', background: '#fff' }}>
    <Picture id={`${id}/photo`} zone={zone} initialSrc={photo?.src} slot focus={crop?.focus}
      initialScale={crop?.initialScale} initialRotate={crop?.rotate} initialCrop={layout.frame.crop}
      style={{ position: 'absolute', inset: 0 }} />
    <FigmaLayers layout={drawn} slots={slots} nudges={NUDGE} />
  </Ground>;
}
